args:
query=query PilotPullRequests($owner: String!, $name: String!, $h0: String!) {
rateLimit { remaining resetAt }
repository(owner: $owner, name: $name) {
o0: pullRequests(headRefName: $h0, states: [OPEN], first: 20, orderBy: { field: CREATED_AT, direction: DESC }) { nodes { ...Open } }
a0: pullRequests(headRefName: $h0, first: 20, orderBy: { field: CREATED_AT, direction: DESC }) { nodes { ...Fields } }
}
}
fragment Fields on PullRequest { number url title state isDraft headRefName isCrossRepository createdAt mergedAt stack { number size baseRefName } stackEntry { position } }
fragment Open on PullRequest { ...Fields commits(last: 1) { nodes { commit { statusCheckRollup { state } } } } }
